<?php
namespace CloudHost247\Ovh\Services;use WHMCS\Database\Capsule;use RuntimeException;
final class ServiceManager
{private$r;function __construct(ConnectionResolver$r){$this->r=$r;}private function binding($id){$s=Capsule::table('mod_cloudhost247_ovh_services')->where('whmcs_service_id',(int)$id)->first();if(!$s||!$s->remote_service_name)throw new RuntimeException('Service is not linked to an OVH service name.');return$s;}private function base($s){return$s->family==='vps'?'/vps/'.rawurlencode($s->remote_service_name):'/dedicated/server/'.rawurlencode($s->remote_service_name);}function details($id){$s=$this->binding($id);return$this->r->endpoint($s->endpoint_id)->get($this->base($s));}function status($id){$s=$this->binding($id);$c=$this->r->endpoint($s->endpoint_id);return$s->family==='vps'?$c->get($this->base($s).'/status'):$c->get($this->base($s));}function ips($id){$s=$this->binding($id);$raw=$this->r->endpoint($s->endpoint_id)->get($s->family==='vps'?$this->base($s).'/ips':'/ip?routedTo.serviceName='.rawurlencode($s->remote_service_name));return array('addresses'=>(new \CloudHost247\Ovh\Normalization\IpNormalizer())->normalize($raw),'raw'=>$raw);}function reboot($id){$s=$this->binding($id);return$this->r->endpoint($s->endpoint_id)->post($this->base($s).'/reboot');}function power($id,$on){$s=$this->binding($id);if($s->family!=='vps')throw new RuntimeException('Power start/stop is only exposed for VPS mappings.');return$this->r->endpoint($s->endpoint_id)->post($this->base($s).($on?'/start':'/stop'));}function terminate($id,$confirmed=false){if(!$confirmed)throw new RuntimeException('Explicit termination confirmation is required.');$s=$this->binding($id);$result=$this->r->endpoint($s->endpoint_id)->post($this->base($s).'/terminate');Capsule::table('mod_cloudhost247_ovh_services')->where('id',$s->id)->update(array('status'=>'terminating','updated_at'=>date('Y-m-d H:i:s')));return$result;}}
